package com.hari.tracea.okhttp

import okhttp3.Interceptor

/**
 * Static provider for the Tracea interceptor, called by ASM-injected bytecode.
 *
 * At build time, the Tracea Gradle plugin rewrites OkHttpClient.Builder.build()
 * calls to first call [getInterceptor] and inject the result via addInterceptor().
 * At runtime, [Tracea.initialize()] calls [install] to set the real interceptor.
 *
 * **WARNING: This class is referenced by generated bytecode.**
 * The class name, package, and [getInterceptor] method signature MUST NOT change
 * without also updating [com.hari.tracea.plugin.instrumentation.OkHttpBuildMethodVisitor].
 */
object TraceaInterceptorProvider {

    @Volatile
    private var interceptor: Interceptor? = null

    /** No-op interceptor returned when SDK is not yet initialized. */
    private val NO_OP = Interceptor { chain -> chain.proceed(chain.request()) }

    /**
     * Called by [com.hari.tracea.Tracea.initialize] to install the real interceptor.
     * Must be called before any OkHttp requests are made for auto-capture to work.
     */
    @JvmStatic
    fun install(interceptor: Interceptor) {
        this.interceptor = interceptor
    }

    /**
     * Called by ASM-injected bytecode at every OkHttpClient.Builder.build() site.
     * Returns the installed interceptor, or a no-op if the SDK hasn't been initialized yet.
     *
     * **DO NOT RENAME** — this method's signature is hardcoded in generated bytecode.
     * @see com.hari.tracea.plugin.instrumentation.OkHttpBuildMethodVisitor
     */
    @JvmStatic
    fun getInterceptor(): Interceptor {
        return interceptor ?: NO_OP
    }

    /**
     * Clears the installed interceptor. Used for testing or when the SDK is torn down.
     */
    @JvmStatic
    fun reset() {
        interceptor = null
    }
}
